'use strict';
(function (root) {
  const sample = [
    ['w01','apple','苹果'],['w02','window','窗户'],['w03','borrow','借入'],['w04','quiet','安静的'],
    ['w05','journey','旅程'],['w06','repair','修理'],['w07','neighbor','邻居'],['w08','choose','选择']
  ].map(([id,english,chinese])=>({id,english,chinese}));
  function csv(text) {
    const rows=[]; let row=[],cell='',quoted=false;
    text=text.replace(/^\uFEFF/,'');
    for(let i=0;i<text.length;i++) {
      const c=text[i];
      if(quoted) { if(c==='"') { if(text[i+1]==='"'){cell+='"';i++;}else quoted=false; } else cell+=c; }
      else if(c==='"') { if(cell!=='') throw Error('CSV 引号格式错误'); quoted=true; }
      else if(c===','){row.push(cell);cell='';}
      else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}
      else cell+=c;
    }
    if(quoted)throw Error('CSV 引号没有闭合');
    row.push(cell);if(row.some(x=>x.trim()))rows.push(row);
    if(!rows.length || rows[0].map(x=>x.trim()).join(',')!=='id,english,chinese')throw Error('表头必须是 id,english,chinese，顺序保持一致');
    return validateWords(rows.slice(1).map((r,i)=>{if(r.length!==3)throw Error('第 '+(i+2)+' 行必须有三列');return {id:r[0].trim(),english:r[1].trim(),chinese:r[2].trim()};}));
  }
  function validateWords(words) {
    if(!Array.isArray(words)||!words.length)throw Error('词表不能为空');
    const ids=new Set();
    for(const w of words){if(!w||['id','english','chinese'].some(k=>typeof w[k]!=='string'||!w[k].trim()))throw Error('每个词条都需要 id、英文和中文');if(ids.has(w.id))throw Error('重复 id：'+w.id);ids.add(w.id);}
    return words.map(w=>({id:w.id,english:w.english,chinese:w.chinese}));
  }
  function initial(){return {version:1,words:sample.map(w=>({...w})),stats:Object.create(null),days:Object.create(null)};}
  function merge(state,words){const map=new Map(state.words.map(w=>[w.id,w]));for(const w of validateWords(words))map.set(w.id,w);state.words=[...map.values()];}
  function match(answer,english){return answer.trim().toLowerCase()===english.trim().toLowerCase();}
  function day(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');}
  function record(state,id,correct,date=day()){
    const s=state.stats[id]||{attempts:0,correct:0,wrong:false};s.attempts++;s.correct+=correct?1:0;s.wrong=!correct;state.stats[id]=s;
    const d=state.days[date]||{attempts:0,correct:0};d.attempts++;d.correct+=correct?1:0;state.days[date]=d;
  }
  function restore(value){
    if(!value||value.version!==1)throw Error('不是本工具支持的备份');
    const words=validateWords(value.words);const stats=Object.create(null);const days=Object.create(null);const ids=new Set(words.map(w=>w.id));
    if(!value.stats||typeof value.stats!=='object'||Array.isArray(value.stats)||!value.days||typeof value.days!=='object'||Array.isArray(value.days))throw Error('备份记录格式错误');
    const valid=s=>s&&Number.isSafeInteger(s.attempts)&&Number.isSafeInteger(s.correct)&&s.attempts>=0&&s.correct>=0&&s.correct<=s.attempts;
    for(const [k,s]of Object.entries(value.stats)){if(!ids.has(k)||!valid(s)||typeof s.wrong!=='boolean')throw Error('备份词条成绩无效');Object.defineProperty(stats,k,{value:{attempts:s.attempts,correct:s.correct,wrong:s.wrong},enumerable:true,writable:true,configurable:true});}
    for(const [k,s]of Object.entries(value.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(k)||!valid(s))throw Error('备份每日成绩无效');days[k]={attempts:s.attempts,correct:s.correct};}
    return {version:1,words,stats,days};
  }
  const api={sample,csv,validateWords,initial,merge,match,day,record,restore};
  if(typeof module!=='undefined')module.exports=api;else root.WordCore=api;
})(typeof globalThis!=='undefined'?globalThis:this);

