(function(root){
'use strict';
const KEY='museum-practice-v1';
function day(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function later(n){const d=new Date();d.setDate(d.getDate()+n);return day(d);}
function parse(text){
 const lines=text.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').split('\n');let cards=[],intro=[],current;
 for(const line of lines){const m=/^##\s+(.+?)\s*$/.exec(line);if(m){current={title:m[1],body:[]};cards.push(current);}else if(current)current.body.push(line);else intro.push(line);}
 if(!cards.length)throw Error('没有找到主题。请用“## 主题”分隔，每个主题下面写正文。');
 const seen=new Set();for(const c of cards){c.body=c.body.join('\n').trim();if(!c.body)throw Error(`“${c.title}”没有正文，未导入。`);if(seen.has(c.title))throw Error('主题标题重复，请改成不同标题。');seen.add(c.title);}
 return {intro:intro.join('\n').trim(),cards};
}
function reconcile(old,material,name){const p=parse(material),records=Object.create(null);for(const c of p.cards){const prev=old&&old.cards.find(x=>x.title===c.title);if(prev&&prev.body===c.body&&old.records[c.title])records[c.title]=old.records[c.title];}return {version:1,material,name,cards:p.cards,intro:p.intro,records};}
function validate(s){if(!s||s.version!==1||typeof s.material!=='string'||typeof s.name!=='string'||!s.records||typeof s.records!=='object'||Array.isArray(s.records))throw Error('备份格式不正确。');const clean=reconcile(null,s.material,s.name);for(const c of clean.cards){const r=s.records[c.title];if(r){if(!Number.isInteger(r.level)||r.level<0||r.level>4||!Number.isInteger(r.count)||r.count<0||typeof r.notes!=='string'||typeof r.due!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(r.due)||!['0','1','2'].includes(String(r.rating)))throw Error('备份中的练习记录无效。');clean.records[c.title]={level:r.level,count:r.count,notes:r.notes,due:r.due,rating:Number(r.rating)};}}return clean;}
function rate(r,value){const level=value===2?Math.min((r?.level||0)+1,4):0;return {level,count:(r?.count||0)+1,notes:r?.notes||'',rating:value,due:later(value===0?1:value===1?2:[0,4,8,16,30][level])};}
function boot(initial){
 const $=id=>document.getElementById(id);let state=reconcile(null,initial,'inputs/讲解资料.md'),queue=[],index=0,done=0,shown=false;
 function message(t){$('message').textContent=t;}
 try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));}catch(e){message('无法读取旧进度，当前使用初始资料。可尝试恢复备份。原因：'+e.message);}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){message('浏览器未能保存；请在关闭前下载完整备份。'+e.message);}}
 function home(){queue=[];$('home').hidden=false;$('practice').hidden=true;$('finish').hidden=true;const due=state.cards.filter(c=>!state.records[c.title]||state.records[c.title].due<=day()).length;$('status').textContent=`${day()} · ${state.cards.length} 个主题`;$('overview').textContent=`今天有 ${due} 个主题需要复习。`;$('daily').disabled=due===0;$('source').textContent='当前资料：'+state.name;$('preamble').textContent=state.intro;}
 function show(){shown=false;$('answer').hidden=true;$('reveal').hidden=false;const c=queue[index];$('counter').textContent=`本轮 ${index+1} / ${queue.length}`;$('question').textContent=c.title;$('notes').value=state.records[c.title]?.notes||'';$('reference').textContent=c.body;$('citation').textContent=`来源：${state.name} → ${c.title}`;$('question').focus();}
 function start(all){queue=state.cards.filter(c=>all||!state.records[c.title]||state.records[c.title].due<=day());if(!queue.length)return;index=0;done=0;$('home').hidden=true;$('finish').hidden=true;$('practice').hidden=false;show();}
 $('daily').onclick=()=>start(false);$('all').onclick=()=>start(true);$('leave').onclick=home;$('again').onclick=home;
 $('notes').oninput=()=>{const c=queue[index];if(!c)return;const r=state.records[c.title]||{level:0,count:0,due:day(),rating:0,notes:''};state.records[c.title]={...r,notes:$('notes').value};save();};
