 document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{if(!shown)return;shown=false;const c=queue[index];state.records[c.title]=rate(state.records[c.title],Number(b.dataset.rate));save();done++;index++;if(index<queue.length)show();else{$('practice').hidden=true;$('finish').hidden=false;$('result').textContent=`完成 ${done} 个主题的讲述与自评。复习日期已安排；可在首页继续练全部主题。`;}});
 $('material').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('文件过大，请使用 2 MB 以内的文本资料。');const next=reconcile(state,await f.text(),f.name);const kept=Object.keys(next.records).length;if(!confirm(`新资料共 ${next.cards.length} 个主题，保留 ${kept} 个未变主题的记录；其余重新练习。是否更新？建议先下载备份。`))return;state=next;save();home();message('资料已更新。');}catch(err){message('未更新资料：'+err.message);}finally{e.target.value='';}};
