 $('restore').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error('备份过大。');const next=validate(JSON.parse(await f.text()));if(!confirm('恢复会替换当前资料和进度，是否继续？'))return;state=next;save();home();message('已恢复资料与进度。');}catch(err){message('未恢复备份：'+err.message);}finally{e.target.value='';}};
 home();
}
const api={parse,reconcile,validate,rate,day,boot};if(typeof module!=='undefined')module.exports=api;else root.Practice=api;
})(typeof window==='undefined'?globalThis:window);

